CREATE OR REPLACE FUNCTION public.read_runtime_credential(p_name text) RETURNS text LANGUAGE sql SECURITY DEFINER SET search_path TO '' AS $$ SELECT decrypted_secret FROM vault.decrypted_secrets WHERE name=p_name AND p_name IN ('CEYO_CRON_SECRET','CEYO_GITHUB_TOKEN','CEYO_SMTP_HOST','CEYO_SMTP_PORT','CEYO_SMTP_USER','CEYO_SMTP_PASSWORD','CEYO_SMTP_FROM') LIMIT 1 $$;
CREATE OR REPLACE FUNCTION public.store_runtime_credential(p_name text,p_value text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO '' AS $$ DECLARE sid uuid; BEGIN IF p_name NOT IN ('CEYO_CRON_SECRET','CEYO_GITHUB_TOKEN','CEYO_SMTP_HOST','CEYO_SMTP_PORT','CEYO_SMTP_USER','CEYO_SMTP_PASSWORD','CEYO_SMTP_FROM') OR p_value IS NULL OR length(p_value)=0 THEN RAISE EXCEPTION 'Invalid credential'; END IF; PERFORM pg_advisory_xact_lock(hashtext(p_name)); SELECT id INTO sid FROM vault.secrets WHERE name=p_name LIMIT 1; IF sid IS NULL THEN PERFORM vault.create_secret(p_value,p_name,'Independent Ceyo runtime'); ELSE PERFORM vault.update_secret(sid,p_value,p_name,'Independent Ceyo runtime'); END IF; END $$;
REVOKE ALL ON FUNCTION public.read_runtime_credential(text),public.store_runtime_credential(text,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.read_runtime_credential(text),public.store_runtime_credential(text,text) TO service_role;